completion_checker:
source=read_json("input.json")
expected={"suffix":[sum(source[i:]) for i in range(len(source))],"total":sum(source)}
raise SystemExit(verify(expected, "result.json", feedback=FEEDBACK))

source=read_json("input.json")
expected={"values":list(dict.fromkeys(source)),"counts":[source.count(v) for v in dict.fromkeys(source)]}
raise SystemExit(verify(expected, "result.json", feedback=FEEDBACK))

source=read_json("input.json")
expected={"hex":[s.encode("utf-8").hex() for s in source],"bytes":[len(s.encode("utf-8")) for s in source]}
raise SystemExit(verify(expected, "result.json", feedback=FEEDBACK))

source=read_json("input.json")
expected={"reversed":[s[::-1] for s in source]}
raise SystemExit(verify(expected, "result.json", feedback=FEEDBACK))
